# 1. Create validate_password function:
def validate_password(password):
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters")
    if not any(char.isdigit() for char in password):
        raise ValueError("Password must contain at least one digit")
    return "Password is valid!"

# 2. Test with valid password:
print("Testing 'Secure123':")
try:
    result = validate_password("Secure123")
    print(result)
except ValueError as e:
    print(f"Error: {e}")

# 3. Test with short password:
print("Testing 'short':")
try:
    result = validate_password("short")
    print(result)
except ValueError as e:
    print(f"Error: {e}")

# 4. Test with no digits:
print("Testing 'NoDigits':")
try:
    result = validate_password("NoDigits")
    print(result)
except ValueError as e:
    print(f"Error: {e}")
